steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      {
        issue(identifier: \"MOB-3\") {
          id
          identifier
          title
          labels {
            id
            name
            group {
              name
            }
          }
        }
        issueLabels(first: 100) {
          nodes {
            id
            name
            group {
              name
            }
          }
        }
      }
    "
  }'
